// ---- core.js ----
// Ported from SD.Core (settlement_defense Unity project). Shared types and a seeded RNG so
// simulation runs are reproducible, matching the C# ulong-seed convention.

function makeRng(seed) {
  let s = seed >>> 0;
  return function rng() {
    s |= 0; s = (s + 0x6D2B79F5) | 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function rngInt(rng, minInclusive, maxExclusive) {
  return minInclusive + Math.floor(rng() * (maxExclusive - minInclusive));
}

function clamp01(v) {
  return v < 0 ? 0 : v > 1 ? 1 : v;
}

function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
}

function gridIndex(width, x, y) {
  return y * width + x;
}

const AggressionPreset = Object.freeze({
  Calm: 'Calm',
  Standard: 'Standard',
  Aggressive: 'Aggressive',
});

const StaffRoleKind = Object.freeze({
  None: 'None',
  Guard: 'Guard',
  Sniper: 'Sniper',
  K9Handler: 'K9Handler',
});

const TerrainKind = Object.freeze({
  Bare: 0,
  Soil: 1,
  Rock: 2,
  Water: 3,
});


// ---- traits.js ----
// Condensed personality traits, matching the RimWorld side of the GDD ("needs/mood/traits").
// Each citizen gets exactly one at spawn; traits are flavor + a small numeric nudge, not a
// deep system, since the core loop doesn't depend on them.
const TRAITS = [
  { name: 'Tough', healthMult: 1.3, hungerMult: 1, restMult: 1, socialGainMult: 1 },
  { name: 'Fast', healthMult: 1, hungerMult: 1, restMult: 1, socialGainMult: 1, speedMult: 1.3 },
  { name: 'Sociable', healthMult: 1, hungerMult: 1, restMult: 1, socialGainMult: 1.5 },
  { name: 'Insomniac', healthMult: 1, hungerMult: 1, restMult: 1.4, socialGainMult: 1 },
  { name: 'Glutton', healthMult: 1, hungerMult: 1.4, restMult: 1, socialGainMult: 1 },
  { name: 'Hardy', healthMult: 1.15, hungerMult: 0.85, restMult: 0.85, socialGainMult: 1 },
  { name: 'Loner', healthMult: 1, hungerMult: 1, restMult: 1, socialGainMult: 0.5 },
  { name: 'Steady', healthMult: 1, hungerMult: 0.9, restMult: 0.9, socialGainMult: 0.9 },
];

function randomTrait(rng) {
  return TRAITS[Math.floor(rng() * TRAITS.length)];
}


// ---- grid.js ----
// Ported from SD.Facility/SettlementGrid.cs.

class SettlementGrid {
  constructor(width, height) {
    this.width = width;
    this.height = height;
    const n = width * height;
    this.terrain = new Uint8Array(n); // TerrainKind, defaults to Bare (0)
    this.wallThingId = new Uint32Array(n); // 0 = no wall
  }

  inBounds(x, y) {
    return x >= 0 && y >= 0 && x < this.width && y < this.height;
  }

  index(x, y) {
    return gridIndex(this.width, x, y);
  }

  isBlocked(x, y) {
    if (!this.inBounds(x, y)) return true;
    const i = this.index(x, y);
    return this.terrain[i] === TerrainKind.Water || this.wallThingId[i] !== 0;
  }

  setTerrain(x, y, kind) {
    if (!this.inBounds(x, y)) return;
    this.terrain[this.index(x, y)] = kind;
  }

  setWall(x, y, thingId) {
    if (!this.inBounds(x, y)) return;
    this.wallThingId[this.index(x, y)] = thingId;
  }
}


// ---- zones.js ----
// Zoning layer: player-painted per-cell zone kinds. Citizens use Food/Bedroom zones as job
// destinations (see jobs.js). Condensed from SD.Facility's zoning system.

const ZoneKind = Object.freeze({
  None: 0,
  Bedroom: 1,
  Food: 2,
  Recreation: 3,
});

const ZONE_COLOR = {
  [ZoneKind.Bedroom]: 'rgba(90,110,220,0.35)',
  [ZoneKind.Food]: 'rgba(220,160,60,0.35)',
  [ZoneKind.Recreation]: 'rgba(90,200,120,0.35)',
};

class ZoneGrid {
  constructor(width, height) {
    this.width = width;
    this.height = height;
    this.kind = new Uint8Array(width * height);
  }

  index(x, y) { return gridIndex(this.width, x, y); }

  set(x, y, kind) {
    if (x < 0 || y < 0 || x >= this.width || y >= this.height) return;
    this.kind[this.index(x, y)] = kind;
  }

  get(x, y) {
    if (x < 0 || y < 0 || x >= this.width || y >= this.height) return ZoneKind.None;
    return this.kind[this.index(x, y)];
  }

  // Nearest cell of the given kind to (fromX, fromY), or null if none painted.
  nearestOfKind(kind, fromX, fromY) {
    let bestDist = Infinity, bestX = -1, bestY = -1;
    for (let y = 0; y < this.height; y++) {
      for (let x = 0; x < this.width; x++) {
        if (this.kind[this.index(x, y)] !== kind) continue;
        const d = (x - fromX) ** 2 + (y - fromY) ** 2;
        if (d < bestDist) { bestDist = d; bestX = x; bestY = y; }
      }
    }
    return bestX >= 0 ? { x: bestX + 0.5, y: bestY + 0.5 } : null;
  }
}


// ---- economy.js ----
// Scrap economy: build costs and combat rewards. Condensed from SD.Siege's scrap balancing.
const BUILD_COST = {
  wall: 2,
  fence: 3,
  trap: 15,
  turret: 25,
};

const SCRAP_PER_KILL = 4;

function canAfford(world, kind) {
  return world.scrap >= (BUILD_COST[kind] || 0);
}

function spend(world, kind) {
  const cost = BUILD_COST[kind] || 0;
  if (world.scrap < cost) return false;
  world.scrap -= cost;
  return true;
}


// ---- citizens.js ----
// Ported/condensed from SD.Sim (CitizenStore, NeedsDecaySystem, NeedsMoodBreakTickGroup,
// SocialInteractionSystem). Struct-of-arrays store, same shape as the C# CitizenStore.

const CitizenFlags = Object.freeze({
  None: 0,
  Dead: 1 << 0,
  OnBreak: 1 << 1,
});

const HUNGER_DECAY = 0.006;   // per tick (10 Hz), matches ARCHITECTURE.md "100ms/tick"
const REST_DECAY = 0.0035;
const SOCIAL_DECAY = 0.0025;
const ON_DUTY_SOCIAL_FULFILLMENT = 0.6; // guards/snipers get partial social fulfillment on duty
const BREAK_MOOD_THRESHOLD = 0.12;

class CitizenStore {
  constructor(capacity) {
    this.capacity = capacity;
    this.count = 0;
    this.id = new Uint32Array(capacity);
    this.name = new Array(capacity).fill('');
    this.x = new Float32Array(capacity);
    this.y = new Float32Array(capacity);
    this.targetX = new Float32Array(capacity);
    this.targetY = new Float32Array(capacity);
    this.hunger = new Float32Array(capacity).fill(1);
    this.rest = new Float32Array(capacity).fill(1);
    this.social = new Float32Array(capacity).fill(1);
    this.mood = new Float32Array(capacity).fill(1);
    this.health = new Float32Array(capacity).fill(1);
    this.flags = new Uint8Array(capacity);
    this.alive = new Uint8Array(capacity);
    this.jobState = new Uint8Array(capacity); // JobState from jobs.js
    this.skillCombat = new Float32Array(capacity);
    this.skillConstruction = new Float32Array(capacity);
    this._staffCooldown = new Float32Array(capacity); // used by siege.js tickStaffCombat
    this.trait = new Array(capacity).fill(null);
    this._nextId = 1;
  }

  spawn(name, x, y, rng = Math.random) {
    if (this.count >= this.capacity) return -1;
    const i = this.count++;
    const id = this._nextId++;
    this.id[i] = id;
    this.name[i] = name;
    this.x[i] = x; this.y[i] = y;
    this.targetX[i] = x; this.targetY[i] = y;
    this.hunger[i] = 1; this.rest[i] = 1; this.social[i] = 1; this.mood[i] = 1; this.health[i] = 1;
    this.flags[i] = CitizenFlags.None;
    this.alive[i] = 1;
    this.trait[i] = randomTrait(rng);
    return i;
  }

  isAliveAt(i) {
    return this.alive[i] === 1 && (this.flags[i] & CitizenFlags.Dead) === 0;
  }
}

// isStaffAt(i) -> bool, used to decide on-duty social fulfillment (guards/snipers don't
// need to be near others to stay socially fulfilled while working).
function tickNeedsAndMood(store, isStaffAt, rng) {
  for (let i = 0; i < store.count; i++) {
    if (!store.isAliveAt(i)) continue;

    const staffFulfillment = isStaffAt(i) ? ON_DUTY_SOCIAL_FULFILLMENT : 0;
    const trait = store.trait[i];

    store.hunger[i] = Math.max(0, store.hunger[i] - HUNGER_DECAY * (trait?.hungerMult ?? 1));
    store.rest[i] = Math.max(0, store.rest[i] - REST_DECAY * (trait?.restMult ?? 1));
    store.social[i] = Math.max(0, store.social[i] - SOCIAL_DECAY * (1 - staffFulfillment));

    const avgNeed = (store.hunger[i] + store.rest[i] + store.social[i]) / 3;
    // Mood eases toward the current need average rather than snapping, so a single bad tick
    // doesn't cause a break.
    store.mood[i] += (avgNeed - store.mood[i]) * 0.05;

    if (store.mood[i] < BREAK_MOOD_THRESHOLD) {
      store.flags[i] |= CitizenFlags.OnBreak;
    } else if (store.mood[i] > BREAK_MOOD_THRESHOLD + 0.1) {
      store.flags[i] &= ~CitizenFlags.OnBreak;
    }
  }
}

// Simple wander: citizens not on a job walk toward a random nearby point, matching the
// "idle wander" behavior visible in the Unity build's default scenario (no job system ported
// yet — this is deliberately simpler than SD.Sim's real Eat/Sleep job execution).
function tickWander(store, grid, rng, speed = 0.04, skipIf = null) {
  for (let i = 0; i < store.count; i++) {
    if (!store.isAliveAt(i)) continue;
    if (skipIf && skipIf(i)) continue;

    const dx = store.targetX[i] - store.x[i];
    const dy = store.targetY[i] - store.y[i];
    const dist = Math.hypot(dx, dy);
    if (dist < 0.15) {
      let tx, ty, tries = 0;
      do {
        tx = Math.max(1, Math.min(grid.width - 2, store.x[i] + (rng() - 0.5) * 10));
        ty = Math.max(1, Math.min(grid.height - 2, store.y[i] + (rng() - 0.5) * 10));
        tries++;
      } while (grid.isBlocked(tx | 0, ty | 0) && tries < 8);
      store.targetX[i] = tx;
      store.targetY[i] = ty;
    } else {
      store.x[i] += (dx / dist) * speed;
      store.y[i] += (dy / dist) * speed;
    }
  }
}


// ---- security.js ----
// Ported/condensed from SD.Security (StaffRoster, guard/sniper/K9 AI + alert-level FSM).

const AlertLevel = Object.freeze({
  Calm: 0,
  Alert: 1,
  Combat: 2,
});

class StaffRoster {
  constructor() {
    this._roleById = new Map(); // citizenId -> StaffRoleKind
    this._postById = new Map(); // citizenId -> {x, y}
  }

  assign(citizenId, kind, post) {
    this._roleById.set(citizenId, kind);
    if (post) this._postById.set(citizenId, post);
  }

  isStaff(citizenId) {
    return this._roleById.has(citizenId);
  }

  kindOf(citizenId) {
    return this._roleById.get(citizenId) || StaffRoleKind.None;
  }

  postOf(citizenId) {
    return this._postById.get(citizenId);
  }
}

// Guards/snipers walk to their assigned post and stay there (matches the Unity build's
// "hold position" staff behavior); everyone else uses the general wander tick.
function tickStaffDuty(store, roster, idOf, speed = 0.05) {
  for (let i = 0; i < store.count; i++) {
    if (!store.isAliveAt(i)) continue;
    const id = idOf(i);
    if (!roster.isStaff(id)) continue;
    const post = roster.postOf(id);
    if (!post) continue;

    const dx = post.x - store.x[i];
    const dy = post.y - store.y[i];
    const dist = Math.hypot(dx, dy);
    if (dist > 0.1) {
      store.x[i] += (dx / dist) * speed;
      store.y[i] += (dy / dist) * speed;
    }
    store.targetX[i] = store.x[i];
    store.targetY[i] = store.y[i];
  }
}

// Guard/sniper engagement range in grid cells, and simple alert-level derivation from
// visible attacker count (Calm -> Alert -> Combat), matching the FSM's broad shape.
function deriveAlertLevel(attackerAliveCount) {
  if (attackerAliveCount === 0) return AlertLevel.Calm;
  return AlertLevel.Combat;
}

const DOG_RANGE = 2.5; const DOG_DAMAGE = 0.08; const DOG_COOLDOWN = 3; const DOG_SPEED = 0.07;

// K9 units: each dog follows its handler loosely and bites the nearest attacker in range,
// fast and cheap per-hit compared to a guard's sidearm -- matches the GDD's non-carceral
// civil-protection-force framing ("guards/snipers/K9/CCTV", never inmates).
function tickDogs(dogs, citizens, roster, attackers, onScrap) {
  for (const dog of dogs) {
    const ownerIdx = findCitizenIndexById(citizens, dog.ownerId);
    if (ownerIdx < 0 || !citizens.isAliveAt(ownerIdx)) continue;

    const dx = citizens.x[ownerIdx] - dog.x;
    const dy = citizens.y[ownerIdx] - dog.y;
    const dist = Math.hypot(dx, dy);
    if (dist > 1.2) {
      dog.x += (dx / dist) * DOG_SPEED;
      dog.y += (dy / dist) * DOG_SPEED;
    }

    if (dog.cooldown > 0) { dog.cooldown--; continue; }
    let bestI = -1, bestDist = DOG_RANGE;
    for (let i = 0; i < attackers.count; i++) {
      if (!attackers.isAliveAt(i)) continue;
      const d = Math.hypot(attackers.x[i] - dog.x, attackers.y[i] - dog.y);
      if (d < bestDist) { bestDist = d; bestI = i; }
    }
    if (bestI >= 0) {
      attackers.health[bestI] -= DOG_DAMAGE;
      dog.cooldown = DOG_COOLDOWN;
      if (attackers.health[bestI] <= 0) { attackers.alive[bestI] = 0; onScrap?.(4); }
    }
  }
}

function findCitizenIndexById(citizens, id) {
  for (let i = 0; i < citizens.count; i++) if (citizens.id[i] === id) return i;
  return -1;
}


// ---- siege.js ----
// Ported/condensed from SD.Siege (wave spawner, AttackerStore, turret/fence/trap placement +
// combat resolution, scrap rewards).


class AttackerStore {
  constructor(capacity) {
    this.capacity = capacity;
    this.count = 0;
    this.x = new Float32Array(capacity);
    this.y = new Float32Array(capacity);
    this.health = new Float32Array(capacity);
    this.alive = new Uint8Array(capacity);
  }

  spawn(x, y, health = 1) {
    if (this.count >= this.capacity) {
      // recycle a dead slot rather than growing, matches the fixed-capacity C# store
      for (let i = 0; i < this.count; i++) {
        if (!this.alive[i]) {
          this.x[i] = x; this.y[i] = y; this.health[i] = health; this.alive[i] = 1;
          return i;
        }
      }
      return -1;
    }
    const i = this.count++;
    this.x[i] = x; this.y[i] = y; this.health[i] = health; this.alive[i] = 1;
    return i;
  }

  isAliveAt(i) {
    return this.alive[i] === 1;
  }
}

class Structure {
  constructor(kind, x, y) {
    this.kind = kind; // 'turret' | 'fence' | 'trap'
    this.x = x; this.y = y;
    this.health = kind === 'fence' ? 0.6 : 1;
    this.destroyed = false;
    this.cooldown = 0;
    this.triggered = false; // traps: single-use
  }
}

class WaveSpawner {
  constructor(grid) {
    this.grid = grid;
    this.nextWaveTick = 300; // 30s at 10Hz, first wave grace period
    this.waveNumber = 0;
    this.strengthFactor = 1; // set by director.js each tick
  }

  tick(currentTick, attackers, rng) {
    if (currentTick < this.nextWaveTick) return;
    this.waveNumber++;
    const count = Math.round((2 + Math.min(10, this.waveNumber * 1.5)) * this.strengthFactor);
    for (let n = 0; n < count; n++) {
      const edge = Math.floor(rng() * 4);
      let x, y;
      if (edge === 0) { x = 0; y = rng() * this.grid.height; }
      else if (edge === 1) { x = this.grid.width - 1; y = rng() * this.grid.height; }
      else if (edge === 2) { x = rng() * this.grid.width; y = 0; }
      else { x = rng() * this.grid.width; y = this.grid.height - 1; }
      attackers.spawn(x, y, (1 + this.waveNumber * 0.1) * Math.max(0.7, this.strengthFactor));
    }
    const delay = 600 - Math.min(300, this.waveNumber * 15);
    this.nextWaveTick = currentTick + Math.round(delay / this.strengthFactor);
  }
}

const TURRET_RANGE = 8;
const TURRET_COOLDOWN_TICKS = 8;
const TURRET_DAMAGE = 0.35;
const ATTACKER_SPEED = 0.03;
const ATTACKER_CITIZEN_DAMAGE = 0.008;
const ATTACKER_CONTACT_RANGE = 0.5;
const FENCE_CONTACT_RANGE = 0.7;
const FENCE_DAMAGE_PER_TICK = 0.015;
const TRAP_TRIGGER_RANGE = 0.5;
const TRAP_DAMAGE = 3; // instant-kill-ish burst
const GUARD_RANGE = 3.5; const GUARD_DAMAGE = 0.05; const GUARD_COOLDOWN = 4;
const SNIPER_RANGE = 9; const SNIPER_DAMAGE = 0.12; const SNIPER_COOLDOWN = 10;

function nearestLivingCitizen(citizens, x, y) {
  let bestI = -1, bestDist = Infinity;
  for (let c = 0; c < citizens.count; c++) {
    if (!citizens.isAliveAt(c)) continue;
    const d = Math.hypot(citizens.x[c] - x, citizens.y[c] - y);
    if (d < bestDist) { bestDist = d; bestI = c; }
  }
  return bestI;
}

// Attackers hunt the nearest living citizen (falling back to the settlement center if the
// colony is somehow empty) and are blocked by un-destroyed fences/walls in their way; they
// chip away at the blocking structure instead of walking through it.
function tickAttackers(attackers, structures, grid, centerX, centerY, citizens, onScrap) {
  for (let i = 0; i < attackers.count; i++) {
    if (!attackers.isAliveAt(i)) continue;

    const blocker = findBlockingFence(structures, attackers.x[i], attackers.y[i]);
    if (blocker) {
      blocker.health -= FENCE_DAMAGE_PER_TICK;
      if (blocker.health <= 0) blocker.destroyed = true;
      continue;
    }

    const targetC = citizens ? nearestLivingCitizen(citizens, attackers.x[i], attackers.y[i]) : -1;
    const tx = targetC >= 0 ? citizens.x[targetC] : centerX;
    const ty = targetC >= 0 ? citizens.y[targetC] : centerY;
    const dx = tx - attackers.x[i];
    const dy = ty - attackers.y[i];
    const dist = Math.hypot(dx, dy);
    if (dist > ATTACKER_CONTACT_RANGE * 0.6) {
      attackers.x[i] += (dx / dist) * ATTACKER_SPEED;
      attackers.y[i] += (dy / dist) * ATTACKER_SPEED;
    }

    for (const t of structures) {
      if (t.kind !== 'trap' || t.triggered) continue;
      if (Math.hypot(attackers.x[i] - t.x, attackers.y[i] - t.y) < TRAP_TRIGGER_RANGE) {
        attackers.health[i] -= TRAP_DAMAGE;
        t.triggered = true; t.destroyed = true;
        if (attackers.health[i] <= 0) { attackers.alive[i] = 0; onScrap?.(SCRAP_PER_KILL); }
      }
    }
  }
}

function findBlockingFence(structures, x, y) {
  for (const s of structures) {
    if (s.kind !== 'fence' || s.destroyed) continue;
    if (Math.hypot(x - s.x, y - s.y) < FENCE_CONTACT_RANGE) return s;
  }
  return null;
}

function tickTurrets(structures, attackers, onScrap) {
  for (const s of structures) {
    if (s.kind !== 'turret' || s.destroyed) continue;
    if (s.cooldown > 0) { s.cooldown--; continue; }

    const bestI = nearestAliveAttacker(attackers, s.x, s.y, TURRET_RANGE);
    if (bestI >= 0) {
      attackers.health[bestI] -= TURRET_DAMAGE;
      if (attackers.health[bestI] <= 0) { attackers.alive[bestI] = 0; onScrap?.(SCRAP_PER_KILL); }
      s.cooldown = TURRET_COOLDOWN_TICKS;
    }
  }
}

function nearestAliveAttacker(attackers, x, y, maxRange) {
  let bestI = -1, bestDist = maxRange;
  for (let i = 0; i < attackers.count; i++) {
    if (!attackers.isAliveAt(i)) continue;
    const d = Math.hypot(attackers.x[i] - x, attackers.y[i] - y);
    if (d < bestDist) { bestDist = d; bestI = i; }
  }
  return bestI;
}

// Attackers in contact range of a living citizen deal damage each tick; citizen dies (Dead
// flag, permadeath per the RimWorld-style design) at 0 health.
function tickAttackerVsCitizens(attackers, citizens) {
  for (let i = 0; i < attackers.count; i++) {
    if (!attackers.isAliveAt(i)) continue;
    for (let c = 0; c < citizens.count; c++) {
      if (!citizens.isAliveAt(c)) continue;
      if (Math.hypot(attackers.x[i] - citizens.x[c], attackers.y[i] - citizens.y[c]) > ATTACKER_CONTACT_RANGE) continue;
      const healthMult = citizens.trait[c]?.healthMult ?? 1;
      citizens.health[c] -= ATTACKER_CITIZEN_DAMAGE / healthMult;
      if (citizens.health[c] <= 0) {
        citizens.flags[c] |= CitizenFlags.Dead;
        citizens.alive[c] = 0;
      }
    }
  }
}

// Guards/snipers fight back with their personal weapon (short/long range respectively),
// separate from turret coverage. Gains combat skill on a confirmed kill.
function tickStaffCombat(citizens, roster, idOf, attackers, onScrap) {
  for (let i = 0; i < citizens.count; i++) {
    if (!citizens.isAliveAt(i)) continue;
    const kind = roster.kindOf(idOf(i));
    if (kind !== 'Guard' && kind !== 'Sniper') continue;

    if (citizens._staffCooldown[i] > 0) { citizens._staffCooldown[i]--; continue; }

    const range = kind === 'Sniper' ? SNIPER_RANGE : GUARD_RANGE;
    const damage = kind === 'Sniper' ? SNIPER_DAMAGE : GUARD_DAMAGE;
    const cooldown = kind === 'Sniper' ? SNIPER_COOLDOWN : GUARD_COOLDOWN;

    const targetI = nearestAliveAttacker(attackers, citizens.x[i], citizens.y[i], range);
    if (targetI >= 0) {
      attackers.health[targetI] -= damage;
      citizens._staffCooldown[i] = cooldown;
      if (attackers.health[targetI] <= 0) {
        attackers.alive[targetI] = 0;
        citizens.skillCombat[i] += 0.05;
        onScrap?.(SCRAP_PER_KILL);
      }
    }
  }
}


// ---- relationships.js ----
// Condensed from SD.Sim's relationship web: nearby citizens slowly build friendship, crossing
// a threshold logs a social event for the HUD feed.
const PROXIMITY = 1.6;
const GROW_RATE = 0.004;
const FRIEND_THRESHOLD = 0.6;

class RelationshipWeb {
  constructor() {
    this.friendship = new Map(); // "idA:idB" (idA<idB) -> value
    this.events = []; // rolling log of {tick, text}
  }

  _key(a, b) { return a < b ? `${a}:${b}` : `${b}:${a}`; }

  tick(store, idOf, currentTick) {
    for (let i = 0; i < store.count; i++) {
      if (!store.isAliveAt(i)) continue;
      for (let j = i + 1; j < store.count; j++) {
        if (!store.isAliveAt(j)) continue;
        const d = Math.hypot(store.x[i] - store.x[j], store.y[i] - store.y[j]);
        if (d > PROXIMITY) continue;

        const key = this._key(idOf(i), idOf(j));
        const before = this.friendship.get(key) || 0;
        const after = Math.min(1, before + GROW_RATE);
        this.friendship.set(key, after);

        if (before < FRIEND_THRESHOLD && after >= FRIEND_THRESHOLD) {
          this.events.push({ tick: currentTick, text: `${store.name[i]} and ${store.name[j]} became friends` });
          if (this.events.length > 20) this.events.shift();
        }
      }
    }
  }
}


// ---- director.js ----
// Condensed from SD.Director: a storyteller that nudges wave timing/size to match colony
// strength, so the siege stays challenging without being unfair to a struggling colony.
function colonyStrength(world) {
  let aliveCitizens = 0;
  for (let i = 0; i < world.citizens.count; i++) if (world.citizens.isAliveAt(i)) aliveCitizens++;

  let structureHealth = 0;
  for (const s of world.structures) if (!s.destroyed) structureHealth += s.health;

  return aliveCitizens * 2 + structureHealth * 3 + world.scrap * 0.1;
}

const AGGRESSION_MULTIPLIER = { Calm: 0.75, Standard: 1, Aggressive: 1.35 };

function directWaveSpawner(world) {
  const strength = colonyStrength(world);
  const mult = AGGRESSION_MULTIPLIER[world.aggression] ?? 1;
  // Stronger colonies get shorter breathers and slightly bigger waves; weak colonies get
  // more breathing room, matching a RimWorld-style storyteller that chases player capability.
  world.waveSpawner.strengthFactor = Math.max(0.6, Math.min(1.8, (strength / 120) * mult));
}


// ---- jobs.js ----
// Real Eat/Sleep job execution, condensed from SD.Sim's job-priority system: citizens with low
// hunger/rest walk to the nearest matching zone and refill there, instead of pure wander.

const JobState = Object.freeze({
  Idle: 0,
  SeekingFood: 1,
  Eating: 2,
  SeekingBed: 3,
  Sleeping: 4,
  SeekingRec: 5,
  Recreating: 6,
});

const SEEK_SOCIAL_THRESHOLD = 0.35;

const SEEK_HUNGER_THRESHOLD = 0.45;
const SEEK_REST_THRESHOLD = 0.4;
const SATISFIED_THRESHOLD = 0.85;
const REFILL_RATE = 0.05; // per tick while occupying the zone
const ARRIVE_DIST = 0.35;
const JOB_SPEED = 0.09; // citizens hustle to zones -- travel time was the dominant cost in the needs loop

function isOnJob(store, i) {
  return store.jobState[i] !== JobState.Idle;
}

function tickJobs(store, zones, staffOnDuty) {
  for (let i = 0; i < store.count; i++) {
    if (!store.isAliveAt(i)) continue;
    if (staffOnDuty(i)) continue; // guards/snipers hold their post, no eat/sleep jobs

    const state = store.jobState[i];

    if (state === JobState.Idle) {
      if (store.rest[i] < SEEK_REST_THRESHOLD) {
        const bed = zones.nearestOfKind(ZoneKind.Bedroom, store.x[i], store.y[i]);
        if (bed) { store.jobState[i] = JobState.SeekingBed; store.targetX[i] = bed.x; store.targetY[i] = bed.y; continue; }
      }
      if (store.hunger[i] < SEEK_HUNGER_THRESHOLD) {
        const food = zones.nearestOfKind(ZoneKind.Food, store.x[i], store.y[i]);
        if (food) { store.jobState[i] = JobState.SeekingFood; store.targetX[i] = food.x; store.targetY[i] = food.y; continue; }
      }
      if (store.social[i] < SEEK_SOCIAL_THRESHOLD) {
        const rec = zones.nearestOfKind(ZoneKind.Recreation, store.x[i], store.y[i]);
        if (rec) { store.jobState[i] = JobState.SeekingRec; store.targetX[i] = rec.x; store.targetY[i] = rec.y; continue; }
      }
      continue;
    }

    if (state === JobState.SeekingFood || state === JobState.SeekingBed || state === JobState.SeekingRec) {
      const dx = store.targetX[i] - store.x[i];
      const dy = store.targetY[i] - store.y[i];
      const dist = Math.hypot(dx, dy);
      if (dist < ARRIVE_DIST) {
        store.jobState[i] = state === JobState.SeekingFood ? JobState.Eating
          : state === JobState.SeekingBed ? JobState.Sleeping
          : JobState.Recreating;
      } else {
        const speed = JOB_SPEED * (store.trait[i]?.speedMult ?? 1);
        store.x[i] += (dx / dist) * speed;
        store.y[i] += (dy / dist) * speed;
      }
      continue;
    }

    if (state === JobState.Eating) {
      store.hunger[i] = Math.min(1, store.hunger[i] + REFILL_RATE);
      if (store.hunger[i] >= SATISFIED_THRESHOLD) store.jobState[i] = JobState.Idle;
      continue;
    }

    if (state === JobState.Sleeping) {
      store.rest[i] = Math.min(1, store.rest[i] + REFILL_RATE);
      if (store.rest[i] >= SATISFIED_THRESHOLD) store.jobState[i] = JobState.Idle;
      continue;
    }

    if (state === JobState.Recreating) {
      store.social[i] = Math.min(1, store.social[i] + REFILL_RATE * (store.trait[i]?.socialGainMult ?? 1));
      if (store.social[i] >= SATISFIED_THRESHOLD) store.jobState[i] = JobState.Idle;
      continue;
    }
  }
}


// ---- world.js ----
// Ported from SD.Headless/SimWorld.cs -- the composition root that owns every store/system
// and advances them one fixed tick at a time (10 Hz, matching ARCHITECTURE.md section 2).










const STARTER_NAMES = [
  'Marlon', 'Aisling', 'Niamh', 'Reeli', 'Cascade', 'Orrery', 'Motoko',
  'Briar', 'Ansel', 'Sable', 'Quinn', 'Vesper', 'Rowan', 'Isolde', 'Callan',
  'Freya', 'Bram', 'Elowen', 'Tavish', 'Maren', 'Cormac', 'Sorcha', 'Declan', 'Aoife',
];

class SimWorld {
  constructor(width, height, seed, aggression = AggressionPreset.Calm, startingCitizens = 24) {
    this.width = width;
    this.height = height;
    this.seed = seed;
    this.aggression = aggression;
    this.rng = makeRng(seed);
    this.currentTick = 0;
    this.paused = false;
    this.gameOver = false;
    this.milestoneLog = [];

    this.grid = new SettlementGrid(width, height);
    this.zones = new ZoneGrid(width, height);
    this.citizens = new CitizenStore(64);
    this.attackers = new AttackerStore(1024);
    this.roster = new StaffRoster();
    this.structures = [];
    this.waveSpawner = new WaveSpawner(this.grid);
    this.relationships = new RelationshipWeb();
    this.scrap = 50;
    this._lastWaveLogged = 0;

    const count = Math.min(startingCitizens, STARTER_NAMES.length);
    this._citizenIds = [];
    for (let n = 0; n < count; n++) {
      const x = 15 + (n % 8) * 2;
      const y = 15 + Math.floor(n / 8) * 2;
      const idx = this.citizens.spawn(STARTER_NAMES[n], x, y, this.rng);
      this._citizenIds.push(this.citizens.id[idx]);
    }

    this.dogs = [];
    if (count > 3) {
      this.roster.assign(this._citizenIds[0], StaffRoleKind.Sniper, { x: 13, y: 20 });
      this.roster.assign(this._citizenIds[1], StaffRoleKind.Sniper, { x: 29, y: 20 });
      this.roster.assign(this._citizenIds[2], StaffRoleKind.Guard, { x: 21, y: 13 });
      this.roster.assign(this._citizenIds[3], StaffRoleKind.Guard, { x: 21, y: 27 });
    }
    if (count > 4) {
      this.roster.assign(this._citizenIds[4], StaffRoleKind.K9Handler, { x: 21, y: 20 });
      this.dogs.push({ ownerId: this._citizenIds[4], x: 21, y: 20, cooldown: 0 });
    }

    for (const [tx, ty] of [[13, 20], [29, 20], [21, 13], [21, 27]]) {
      this.structures.push(new Structure('turret', tx, ty));
    }

    // Default zones so the job system has somewhere to send citizens out of the box.
    for (let x = 17; x <= 20; x++) for (let y = 17; y <= 20; y++) this.zones.set(x, y, ZoneKind.Food);
    for (let x = 22; x <= 25; x++) for (let y = 17; y <= 20; y++) this.zones.set(x, y, ZoneKind.Bedroom);
    for (let x = 17; x <= 20; x++) for (let y = 22; y <= 23; y++) this.zones.set(x, y, ZoneKind.Recreation);
  }

  idOf(i) { return this.citizens.id[i]; }
  isStaffAt(i) { return this.roster.isStaff(this.citizens.id[i]); }

  addScrap(amount) { this.scrap += amount; }

  build(kind, x, y) {
    this.structures.push(new Structure(kind, x, y));
  }

  tick() {
    if (this.paused || this.gameOver) return;
    this.currentTick++;

    tickNeedsAndMood(this.citizens, (i) => this.isStaffAt(i), this.rng);
    tickJobs(this.citizens, this.zones, (i) => this.isStaffAt(i));
    tickStaffDuty(this.citizens, this.roster, (i) => this.idOf(i));
    tickWander(this.citizens, this.grid, this.rng, 0.04, (i) => this.isStaffAt(i) || isOnJob(this.citizens, i));
    tickDogs(this.dogs, this.citizens, this.roster, this.attackers, (amt) => this.addScrap(amt));
    this.relationships.tick(this.citizens, (i) => this.citizens.name[i], this.currentTick);

    directWaveSpawner(this);
    this.waveSpawner.tick(this.currentTick, this.attackers, this.rng);
    tickAttackers(this.attackers, this.structures, this.grid, this.width / 2, this.height / 2, this.citizens, (amt) => this.addScrap(amt));
    tickTurrets(this.structures, this.attackers, (amt) => this.addScrap(amt));
    tickStaffCombat(this.citizens, this.roster, (i) => this.idOf(i), this.attackers, (amt) => this.addScrap(amt));
    tickAttackerVsCitizens(this.attackers, this.citizens);

    if (this.waveSpawner.waveNumber > this._lastWaveLogged) {
      this._lastWaveLogged = this.waveSpawner.waveNumber;
      this.milestoneLog.push({ tick: this.currentTick, text: `Wave ${this.waveSpawner.waveNumber} incoming` });
      if (this.milestoneLog.length > 20) this.milestoneLog.shift();
    }

    let aliveCitizens = 0;
    for (let i = 0; i < this.citizens.count; i++) if (this.citizens.isAliveAt(i)) aliveCitizens++;
    if (aliveCitizens === 0 && this.citizens.count > 0) {
      this.gameOver = true;
      this.milestoneLog.push({ tick: this.currentTick, text: 'GAME OVER -- the settlement has fallen' });
    }
  }

  serialize() {
    return {
      width: this.width, height: this.height, seed: this.seed, aggression: this.aggression,
      currentTick: this.currentTick, scrap: this.scrap, gameOver: this.gameOver,
      waveNumber: this.waveSpawner.waveNumber, nextWaveTick: this.waveSpawner.nextWaveTick,
      citizens: {
        count: this.citizens.count,
        id: Array.from(this.citizens.id.slice(0, this.citizens.count)),
        name: this.citizens.name.slice(0, this.citizens.count),
        x: Array.from(this.citizens.x.slice(0, this.citizens.count)),
        y: Array.from(this.citizens.y.slice(0, this.citizens.count)),
        hunger: Array.from(this.citizens.hunger.slice(0, this.citizens.count)),
        rest: Array.from(this.citizens.rest.slice(0, this.citizens.count)),
        social: Array.from(this.citizens.social.slice(0, this.citizens.count)),
        mood: Array.from(this.citizens.mood.slice(0, this.citizens.count)),
        health: Array.from(this.citizens.health.slice(0, this.citizens.count)),
        alive: Array.from(this.citizens.alive.slice(0, this.citizens.count)),
        flags: Array.from(this.citizens.flags.slice(0, this.citizens.count)),
        skillCombat: Array.from(this.citizens.skillCombat.slice(0, this.citizens.count)),
        trait: this.citizens.trait.slice(0, this.citizens.count).map(t => t?.name ?? null),
      },
      roster: Array.from(this.roster._roleById.entries()).map(([id, kind]) => ({
        id, kind, post: this.roster._postById.get(id) || null,
      })),
      structures: this.structures.map(s => ({ kind: s.kind, x: s.x, y: s.y, health: s.health, destroyed: s.destroyed })),
      zones: Array.from(this.zones.kind),
      dogs: this.dogs.map(d => ({ ownerId: d.ownerId, x: d.x, y: d.y })),
    };
  }

  static deserialize(json) {
    const w = new SimWorld(json.width, json.height, json.seed, json.aggression, 0);
    w.currentTick = json.currentTick;
    w.scrap = json.scrap;
    w.gameOver = json.gameOver || false;
    w.waveSpawner.waveNumber = json.waveNumber || 0;
    w.waveSpawner.nextWaveTick = json.nextWaveTick || 300;
    const c = json.citizens;
    w.citizens.count = c.count;
    for (let i = 0; i < c.count; i++) {
      w.citizens.id[i] = c.id[i];
      w.citizens.name[i] = c.name[i];
      w.citizens.x[i] = c.x[i]; w.citizens.y[i] = c.y[i];
      w.citizens.targetX[i] = c.x[i]; w.citizens.targetY[i] = c.y[i];
      w.citizens.hunger[i] = c.hunger[i]; w.citizens.rest[i] = c.rest[i]; w.citizens.social[i] = c.social[i];
      w.citizens.mood[i] = c.mood[i]; w.citizens.health[i] = c.health[i]; w.citizens.alive[i] = c.alive[i];
      w.citizens.flags[i] = c.flags ? c.flags[i] : 0;
      w.citizens.skillCombat[i] = c.skillCombat ? c.skillCombat[i] : 0;
      w.citizens.trait[i] = c.trait && c.trait[i] ? TRAITS.find(t => t.name === c.trait[i]) : null;
    }
    w.roster = new (Object.getPrototypeOf(w.roster).constructor)();
    for (const r of json.roster) w.roster.assign(r.id, r.kind, r.post);
    w.structures = json.structures.map(s => Object.assign(new Structure(s.kind, s.x, s.y), s));
    if (json.zones) w.zones.kind.set(json.zones);
    if (json.dogs) w.dogs = json.dogs.map(d => ({ ...d, cooldown: 0 }));
    return w;
  }
}


// ---- render.js ----
// Procedural renderer -- draws every sprite with Canvas 2D shape primitives instead of AI-
// generated images, per the "generate assets in-house" decision (no external art pipeline).


const CELL = 24; // px per grid cell at zoom 1

const ROLE_COLOR = {
  [StaffRoleKind.Guard]: '#f2c026',
  [StaffRoleKind.Sniper]: '#bf59d9',
  [StaffRoleKind.K9Handler]: '#f2c026',
  [StaffRoleKind.None]: '#d9d9de',
};

// Deterministic per-cell noise so the ground doesn't need an image asset to avoid looking flat.
function cellNoise(x, y) {
  const n = Math.sin(x * 127.1 + y * 311.7) * 43758.5453;
  return n - Math.floor(n);
}

class Renderer {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.camX = 0; this.camY = 0; this.zoom = 1;
  }

  resize() {
    // window.innerWidth/Height can briefly report 0 before layout settles in some embedding
    // contexts; falling back to a sane default avoids getting stuck with a 0x0 canvas forever
    // (nothing else would ever retry since main.js only calls this on the 'resize' event).
    const w = window.innerWidth || 1280;
    const h = window.innerHeight || 720;
    if (this.canvas.width === w && this.canvas.height === h) return;
    this.canvas.width = w;
    this.canvas.height = h;
  }

  frameOnContent(world) {
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (let i = 0; i < world.citizens.count; i++) {
      if (!world.citizens.isAliveAt(i)) continue;
      minX = Math.min(minX, world.citizens.x[i]); maxX = Math.max(maxX, world.citizens.x[i]);
      minY = Math.min(minY, world.citizens.y[i]); maxY = Math.max(maxY, world.citizens.y[i]);
    }
    for (const s of world.structures) {
      minX = Math.min(minX, s.x); maxX = Math.max(maxX, s.x);
      minY = Math.min(minY, s.y); maxY = Math.max(maxY, s.y);
    }
    if (!isFinite(minX)) { minX = 0; maxX = world.width; minY = 0; maxY = world.height; }
    const pad = 6;
    const w = (maxX - minX) + pad * 2;
    const h = (maxY - minY) + pad * 2;
    this.camX = (minX + maxX) / 2;
    this.camY = (minY + maxY) / 2;
    const zoomX = this.canvas.width / (w * CELL);
    const zoomY = this.canvas.height / (h * CELL);
    this.zoom = Math.max(0.4, Math.min(2.5, Math.min(zoomX, zoomY)));
  }

  worldToScreen(x, y) {
    return [
      this.canvas.width / 2 + (x - this.camX) * CELL * this.zoom,
      this.canvas.height / 2 + (y - this.camY) * CELL * this.zoom,
    ];
  }

  screenToWorld(sx, sy) {
    return [
      this.camX + (sx - this.canvas.width / 2) / (CELL * this.zoom),
      this.camY + (sy - this.canvas.height / 2) / (CELL * this.zoom),
    ];
  }

  draw(world, input) {
    const ctx = this.ctx;
    ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
    this._drawGround(world);
    this._drawZones(world);
    this._drawStructures(world);
    this._drawCitizens(world);
    this._drawDogs(world);
    this._drawAttackers(world);
    if (input) {
      this._drawCursor(world, input);
      this._drawSelection(world, input);
    }
  }

  _drawSelection(world, input) {
    const sel = input.selectedCitizen;
    if (sel == null || sel < 0 || sel >= world.citizens.count || !world.citizens.isAliveAt(sel)) return;
    const ctx = this.ctx;
    const [sx, sy] = this.worldToScreen(world.citizens.x[sel], world.citizens.y[sel]);
    const r = CELL * this.zoom * 0.5;
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(sx, sy, r, 0, Math.PI * 2);
    ctx.stroke();
  }

  _drawZones(world) {
    const ctx = this.ctx;
    const size = CELL * this.zoom;
    for (let y = 0; y < world.height; y++) {
      for (let x = 0; x < world.width; x++) {
        const kind = world.zones.get(x, y);
        if (kind === ZoneKind.None) continue;
        const [px, py] = this.worldToScreen(x, y);
        ctx.fillStyle = ZONE_COLOR[kind];
        ctx.fillRect(px, py, size + 1, size + 1);
      }
    }
  }

  _drawCursor(world, input) {
    const ctx = this.ctx;
    if (!input.hoverGridX && input.hoverGridX !== 0) return;
    const [px, py] = this.worldToScreen(input.hoverGridX, input.hoverGridY);
    const size = CELL * this.zoom;
    ctx.strokeStyle = input.tool ? '#ffffff' : 'rgba(255,255,255,0.3)';
    ctx.lineWidth = 2;
    ctx.strokeRect(px + 1, py + 1, size - 2, size - 2);
  }

  _drawGround(world) {
    const ctx = this.ctx;
    const [x0, y0] = this.worldToScreen(0, 0);
    const size = CELL * this.zoom;
    const startCol = Math.max(0, Math.floor(-x0 / size));
    const startRow = Math.max(0, Math.floor(-y0 / size));
    const endCol = Math.min(world.width, Math.ceil((this.canvas.width - x0) / size));
    const endRow = Math.min(world.height, Math.ceil((this.canvas.height - y0) / size));

    for (let gy = startRow; gy < endRow; gy++) {
      for (let gx = startCol; gx < endCol; gx++) {
        const idx = world.grid.index(gx, gy);
        const kind = world.grid.terrain[idx];
        const hasWall = world.grid.wallThingId[idx] !== 0;
        const n = cellNoise(gx, gy);
        let base = [0.55, 0.42, 0.28]; // dirt brown, matches the GDD's scavenged-settlement palette
        if (kind === TerrainKind.Soil) base = [0.42, 0.32, 0.20];
        else if (kind === TerrainKind.Rock) base = [0.5, 0.5, 0.52];
        else if (kind === TerrainKind.Water) base = [0.18, 0.35, 0.55];
        if (hasWall) base = [0.17, 0.16, 0.19];

        const shade = 0.85 + n * 0.3;
        const r = Math.round(base[0] * 255 * shade);
        const g = Math.round(base[1] * 255 * shade);
        const b = Math.round(base[2] * 255 * shade);
        ctx.fillStyle = `rgb(${r},${g},${b})`;
        const px = x0 + gx * size, py = y0 + gy * size;
        ctx.fillRect(px, py, size + 1, size + 1);
      }
    }
  }

  _drawHumanoid(x, y, scale, bodyColor, headColor, healthFrac) {
    const ctx = this.ctx;
    const [sx, sy] = this.worldToScreen(x, y);
    const s = CELL * this.zoom * scale;
    ctx.fillStyle = 'rgba(0,0,0,0.35)';
    ctx.beginPath();
    ctx.ellipse(sx, sy + s * 0.42, s * 0.28, s * 0.12, 0, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = bodyColor;
    ctx.fillRect(sx - s * 0.18, sy - s * 0.1, s * 0.36, s * 0.42);

    ctx.fillStyle = headColor;
    ctx.beginPath();
    ctx.arc(sx, sy - s * 0.28, s * 0.2, 0, Math.PI * 2);
    ctx.fill();

    if (healthFrac !== undefined && healthFrac < 0.98) {
      const barW = s * 0.5, barY = sy - s * 0.55;
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(sx - barW / 2, barY, barW, s * 0.08);
      ctx.fillStyle = healthFrac > 0.5 ? '#5fd15f' : healthFrac > 0.25 ? '#e0c040' : '#e05050';
      ctx.fillRect(sx - barW / 2, barY, barW * Math.max(0, healthFrac), s * 0.08);
    }
  }

  _drawCitizens(world) {
    for (let i = 0; i < world.citizens.count; i++) {
      if (!world.citizens.isAliveAt(i)) continue;
      const id = world.citizens.id[i];
      const role = world.roster.isStaff(id) ? world.roster.kindOf(id) : StaffRoleKind.None;
      const color = ROLE_COLOR[role] || ROLE_COLOR[StaffRoleKind.None];
      this._drawHumanoid(world.citizens.x[i], world.citizens.y[i], 0.7, color, '#e8c9a0', world.citizens.health[i]);
    }
  }

  _drawDogs(world) {
    const ctx = this.ctx;
    for (const dog of world.dogs || []) {
      const [sx, sy] = this.worldToScreen(dog.x, dog.y);
      const s = CELL * this.zoom * 0.4;
      ctx.fillStyle = '#7a5230';
      ctx.beginPath();
      ctx.ellipse(sx, sy, s * 0.32, s * 0.2, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.beginPath();
      ctx.arc(sx + s * 0.28, sy - s * 0.05, s * 0.14, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  _drawAttackers(world) {
    for (let i = 0; i < world.attackers.count; i++) {
      if (!world.attackers.isAliveAt(i)) continue;
      this._drawHumanoid(world.attackers.x[i], world.attackers.y[i], 0.6, '#8a1f1f', '#c76b4a', world.attackers.health[i]);
    }
  }

  _drawStructures(world) {
    const ctx = this.ctx;
    for (const s of world.structures) {
      if (s.destroyed && s.kind === 'trap') continue; // traps vanish once triggered
      const [sx, sy] = this.worldToScreen(s.x, s.y);
      const size = CELL * this.zoom * 0.85;

      if (s.kind === 'fence') {
        ctx.strokeStyle = s.destroyed ? 'rgba(80,60,40,0.4)' : '#a8825a';
        ctx.lineWidth = Math.max(2, size * 0.12);
        ctx.beginPath();
        ctx.moveTo(sx - size / 2, sy);
        ctx.lineTo(sx + size / 2, sy);
        ctx.stroke();
        continue;
      }

      if (s.kind === 'trap') {
        ctx.fillStyle = 'rgba(140,20,20,0.55)';
        ctx.beginPath();
        ctx.arc(sx, sy, size * 0.3, 0, Math.PI * 2);
        ctx.fill();
        continue;
      }

      ctx.fillStyle = s.destroyed ? 'rgba(60,60,60,0.6)' : '#8c949e';
      ctx.fillRect(sx - size / 2, sy - size / 2, size, size);
      if (s.kind === 'turret' && !s.destroyed) {
        ctx.fillStyle = '#2b2b2b';
        ctx.fillRect(sx - size * 0.08, sy - size * 0.6, size * 0.16, size * 0.4);
      }
    }
  }
}


// ---- input.js ----
// Player input: build palette, zone painting, pause/speed. This is what turns the sim into an
// actual game instead of a passive screensaver -- there was no player agency before this.


const TOOLS = [
  { key: '0', tool: null, label: 'Select', cost: null },
  { key: '1', tool: 'wall', label: 'Wall', cost: BUILD_COST.wall },
  { key: '2', tool: 'turret', label: 'Turret', cost: BUILD_COST.turret },
  { key: '3', tool: 'fence', label: 'Fence', cost: BUILD_COST.fence },
  { key: '4', tool: 'trap', label: 'Trap', cost: BUILD_COST.trap },
  { key: '5', tool: 'zone-food', label: 'Food Zone', cost: null },
  { key: '6', tool: 'zone-bedroom', label: 'Bedroom Zone', cost: null },
  { key: '7', tool: 'zone-recreation', label: 'Recreation Zone', cost: null },
];

const TOOL_KEYS = Object.fromEntries(TOOLS.map(t => [t.key, t.tool]));
TOOL_KEYS['Escape'] = null;

class InputController {
  constructor(canvas, renderer, getWorld, onSpeedChange, onToast) {
    this.canvas = canvas;
    this.renderer = renderer;
    this.getWorld = getWorld;
    this.onSpeedChange = onSpeedChange;
    this.onToast = onToast;
    this.tool = null;
    this.hoverGridX = null;
    this.hoverGridY = null;
    this.speedIndex = 1; // index into SPEEDS
    this.SPEEDS = [0, 1, 2, 4];
    this._painting = false;
    this.selectedCitizen = -1;

    canvas.addEventListener('mousemove', (e) => this._onMove(e));
    canvas.addEventListener('mousedown', (e) => this._onDown(e));
    canvas.addEventListener('mouseup', () => { this._painting = false; });
    canvas.addEventListener('mouseleave', () => { this.hoverGridX = null; this.hoverGridY = null; this._painting = false; });
    window.addEventListener('keydown', (e) => this._onKey(e));
  }

  setTool(tool) {
    this.tool = tool;
  }

  togglePause() {
    const w = this.getWorld();
    if (w) w.paused = !w.paused;
  }

  setSpeedIndex(i) {
    this.speedIndex = Math.max(0, Math.min(this.SPEEDS.length - 1, i));
    this.onSpeedChange?.(this.SPEEDS[this.speedIndex]);
  }

  _onMove(e) {
    const rect = this.canvas.getBoundingClientRect();
    const [wx, wy] = this.renderer.screenToWorld(e.clientX - rect.left, e.clientY - rect.top);
    this.hoverWorldX = wx; this.hoverWorldY = wy;
    this.hoverGridX = Math.floor(wx);
    this.hoverGridY = Math.floor(wy);
    if (this._painting) this._place();
  }

  _onDown(e) {
    if (e.button !== 0) return;
    this._painting = true;
    this._place();
  }

  _place() {
    const world = this.getWorld();
    if (!world || this.hoverGridX == null) return;

    if (!this.tool) {
      this._pickCitizen(world);
      return;
    }

    const x = this.hoverGridX, y = this.hoverGridY;
    if (x < 0 || y < 0 || x >= world.width || y >= world.height) return;

    if (this.tool.startsWith('zone-')) {
      const kind = { 'zone-food': ZoneKind.Food, 'zone-bedroom': ZoneKind.Bedroom, 'zone-recreation': ZoneKind.Recreation }[this.tool];
      world.zones.set(x, y, kind);
      return;
    }

    if (world.grid.wallThingId[world.grid.index(x, y)] !== 0) { this.onToast?.('Already occupied'); return; }
    for (const s of world.structures) {
      if (!s.destroyed && Math.floor(s.x) === x && Math.floor(s.y) === y) { this.onToast?.('Already occupied'); return; }
    }

    if (!canAfford(world, this.tool)) { this.onToast?.('Not enough scrap'); return; }
    spend(world, this.tool);
    if (this.tool === 'wall') {
      world.grid.setWall(x, y, 1);
    } else {
      world.build(this.tool, x + 0.5, y + 0.5);
    }
  }

  _pickCitizen(world) {
    let bestI = -1, bestDist = 0.8; // pick radius in world units
    for (let i = 0; i < world.citizens.count; i++) {
      if (!world.citizens.isAliveAt(i)) continue;
      const d = Math.hypot(world.citizens.x[i] - this.hoverWorldX, world.citizens.y[i] - this.hoverWorldY);
      if (d < bestDist) { bestDist = d; bestI = i; }
    }
    this.selectedCitizen = bestI;
  }

  _onKey(e) {
    if (e.key in TOOL_KEYS) { this.setTool(TOOL_KEYS[e.key]); return; }
    if (e.key === ' ') { e.preventDefault(); this.togglePause(); return; }
    if (e.key === '+' || e.key === '=') { this.setSpeedIndex(this.speedIndex + 1); return; }
    if (e.key === '-') { this.setSpeedIndex(this.speedIndex - 1); return; }
  }
}


// ---- main.js ----
// Ported from SD.Presentation/SimWorldHost.cs -- owns one SimWorld, steps it at a fixed
// 10 Hz tick rate independent of frame rate, and renders every frame.



const SECONDS_PER_TICK = 0.1;
const SAVE_KEY = 'settlement-defense-save';

const canvas = document.getElementById('game');
const renderer = new Renderer(canvas);
renderer.resize();
window.addEventListener('resize', () => renderer.resize());

let world = new SimWorld(64, 64, 12345, 'Calm', 24);
renderer.frameOnContent(world);

let speedMultiplier = 1;
let toastTimer = 0;
const toastEl = document.getElementById('toast');

function showToast(msg) {
  toastEl.textContent = msg;
  toastEl.classList.add('show');
  toastTimer = 20; // frames, ~2s at 10Hz
}

const input = new InputController(canvas, renderer, () => world, (s) => { speedMultiplier = s; }, showToast);

window.__debug = { getWorld: () => world, input, renderer };

// ---------------------------------------------------------------- toolbar (built once)
const toolbarEl = document.getElementById('toolbar');
for (const t of TOOLS) {
  const btn = document.createElement('div');
  btn.className = 'tool-btn';
  btn.dataset.tool = t.tool ?? '';
  btn.innerHTML = `<span><span class="key">[${t.key}]</span>${t.label}</span>` +
    (t.cost != null ? `<span class="cost">$${t.cost}</span>` : '');
  btn.addEventListener('click', () => input.setTool(t.tool));
  toolbarEl.appendChild(btn);
}

function syncToolbarHighlight() {
  for (const btn of toolbarEl.children) {
    const btnTool = btn.dataset.tool || null;
    btn.classList.toggle('active', btnTool === input.tool);
  }
}

// ---------------------------------------------------------------- topbar controls
const pauseBtn = document.getElementById('btn-pause');
pauseBtn.addEventListener('click', () => input.togglePause());
document.getElementById('btn-speed-down').addEventListener('click', () => input.setSpeedIndex(input.speedIndex - 1));
document.getElementById('btn-speed-up').addEventListener('click', () => input.setSpeedIndex(input.speedIndex + 1));
document.getElementById('btn-save').addEventListener('click', () => save());
document.getElementById('btn-load').addEventListener('click', () => load());
document.getElementById('btn-restart').addEventListener('click', () => restart());
document.getElementById('btn-restart-modal').addEventListener('click', () => restart());

function save() {
  localStorage.setItem(SAVE_KEY, JSON.stringify(world.serialize()));
  showToast('Saved');
  console.log(`[SimWorldHost] Saved at tick ${world.currentTick}.`);
}

function load() {
  const raw = localStorage.getItem(SAVE_KEY);
  if (!raw) { showToast('No save found'); return; }
  world = SimWorld.deserialize(JSON.parse(raw));
  renderer.frameOnContent(world);
  showToast('Loaded');
  console.log(`[SimWorldHost] Loaded from tick ${world.currentTick}.`);
}

function restart() {
  const seed = Math.floor(Math.random() * 0xffffffff);
  world = new SimWorld(64, 64, seed, 'Calm', 24);
  renderer.frameOnContent(world);
  input.selectedCitizen = -1;
  console.log(`[SimWorldHost] New settlement, seed ${seed}.`);
}

window.addEventListener('keydown', (e) => {
  if (e.key === 'F5') { e.preventDefault(); save(); }
  if (e.key === 'F9') { e.preventDefault(); load(); }
  if (e.key === 'r' || e.key === 'R') { restart(); }
});

// ---------------------------------------------------------------- inspector panel
const inspectorEl = document.getElementById('inspector');
function updateInspector() {
  const sel = input.selectedCitizen;
  if (sel < 0 || sel >= world.citizens.count || !world.citizens.isAliveAt(sel)) {
    if (sel >= 0) input.selectedCitizen = -1;
    inspectorEl.classList.add('hidden');
    return;
  }
  inspectorEl.classList.remove('hidden');
  const c = world.citizens;
  const role = world.roster.isStaff(c.id[sel]) ? world.roster.kindOf(c.id[sel]) : 'Citizen';
  document.getElementById('insp-name').textContent = c.name[sel];
  document.getElementById('insp-role').textContent = `${role} · ${c.trait[sel]?.name ?? ''}`;
  setBar('hp', c.health[sel]);
  setBar('hunger', c.hunger[sel]);
  setBar('rest', c.rest[sel]);
  setBar('social', c.social[sel]);
  setBar('mood', c.mood[sel]);
  document.getElementById('insp-skill').textContent = `Combat skill: ${c.skillCombat[sel].toFixed(2)}`;
}

function setBar(name, frac) {
  const pct = Math.max(0, Math.min(100, Math.round(frac * 100)));
  document.getElementById(`insp-${name}`).style.width = pct + '%';
  document.getElementById(`insp-${name}-pct`).textContent = pct + '%';
}

// ---------------------------------------------------------------- event log + game over
const eventlogEl = document.getElementById('eventlog');
let lastLoggedCount = 0;
function updateEventLog() {
  if (world.milestoneLog.length === lastLoggedCount) return;
  lastLoggedCount = world.milestoneLog.length;
  eventlogEl.innerHTML = world.milestoneLog.slice(-4).map(e => `<div class="entry">${e.text}</div>`).join('');
}

const gameoverEl = document.getElementById('gameover');
function updateGameOver() {
  if (!world.gameOver) { gameoverEl.classList.add('hidden'); return; }
  gameoverEl.classList.remove('hidden');
  document.getElementById('gameover-detail').textContent =
    `Survived ${world.waveSpawner.waveNumber} waves, tick ${world.currentTick}.`;
}

// ---------------------------------------------------------------- topbar stats
function updateTopbar() {
  document.getElementById('stat-scrap').textContent = world.scrap;
  document.getElementById('stat-citizens').textContent = countAlive(world.citizens.count, world.citizens.isAliveAt.bind(world.citizens));
  document.getElementById('stat-attackers').textContent = countAlive(world.attackers.count, world.attackers.isAliveAt.bind(world.attackers));
  document.getElementById('stat-wave').textContent = world.waveSpawner.waveNumber;
  pauseBtn.textContent = world.paused ? '▶ Resume' : '⏸ Pause';
  pauseBtn.classList.toggle('active', world.paused);
  document.getElementById('speed-label').textContent = speedMultiplier + 'x';
}

function countAlive(count, isAliveAt) {
  let n = 0;
  for (let i = 0; i < count; i++) if (isAliveAt(i)) n++;
  return n;
}

let framesSinceReframe = 0;

function frame() {
  renderer.resize();
  for (let s = 0; s < speedMultiplier; s++) world.tick();

  renderer.draw(world, input);

  framesSinceReframe++;
  if (framesSinceReframe > 50) { framesSinceReframe = 0; renderer.frameOnContent(world); }

  updateTopbar();
  syncToolbarHighlight();
  updateInspector();
  updateEventLog();
  updateGameOver();

  if (toastTimer > 0) { toastTimer--; if (toastTimer === 0) toastEl.classList.remove('show'); }
}

// setInterval instead of requestAnimationFrame: rAF is paused entirely in backgrounded/
// non-visible tabs in some embedding contexts, which would silently freeze the sim. A fixed
// 10Hz interval matches the tick rate directly and isn't subject to that pause.
setInterval(frame, SECONDS_PER_TICK * 1000);
